def ref(org, url, supports, version=None):
    return dict(organization=org, url=url, supports=supports, version=version or f"{DATE}网页核对；原页未标发布日期", checked_at=DATE)


def article(ident, title, species, kind, topic, keywords, sections, refs, breeds=None):
    return dict(id=ident, title=title, species=species, content_kind=kind, topic=topic,
        keywords=keywords, life_stages=["all"], breed_ids=breeds or [],
        body="\n\n".join(sections), references=refs,
        source_organization=refs[0]["organization"], source_url=refs[0]["url"],
        source_version=refs[0]["version"], published_at=None, ingested_at=STAMP,
        updated_at=STAMP, review_status="editorial_summary_unreviewed")


